<template>
    <div class="main-box">
        <div>
            <!--    左侧的图片-->
            <!-- <div class="image-box">
        <img :src="baseApi + good.imgs" class="image" />
      </div> -->

            <div class="image-container">
                <img :src="baseApi + good.imgs" alt="Your Image" />
            </div>
            <!--    右侧盒子-->
            <div class="detail-box">
                <!--      商品名与描述-->
                <div>
                    <span style="font-size: 22px"
                        ><strong>{{ good.name }}</strong></span
                    ><br />
                    <div style="margin-top: 8px">
                        <el-tag v-if="isOffShelf" type="info">已下架</el-tag>
                        <el-tag v-else-if="isSoldOutAll" type="danger">售罄</el-tag>
                        <el-tag v-else type="success">上架</el-tag>
                    </div>
                </div>
                <div style="margin-top: 20px">
                    <span style="font-size: 17px">{{ good.description }}</span>
                </div>
                <!--      价格盒子-->

                <div class="price-box" v-if="good.discount < 1">
                    <dl>
                        <div>
                            <dt>原价</dt>
                            <dd style="text-decoration: line-through">
                                <b>{{ price }}</b
                                >元
                            </dd>
                        </div>
                        <div>
                            <dt>折扣</dt>
                            <dd>{{ discount }}</dd>
                        </div>
                        <div>
                            <dt>现价</dt>
                            <dd style="color: red; font-size: 25px">
                                <b>{{ realPrice }}</b
                                >元
                            </dd>
                        </div>
                    </dl>
                </div>
                <div class="price-box" v-if="good.discount === 1">
                    <dl>
                        <div>
                            <dt>价格</dt>
                            <dd style="color: red; font-size: 25px">
                                ￥ <b>{{ price }}</b>
                            </dd>
                        </div>
                    </dl>
                </div>
                <!--      月销量-->
                <div style="margin-top: 20px">
                    <span>月销量：</span>
                    <span>{{ good.sales }}</span
                    ><br />
                    <span style="height: 40px" v-if="showStore"
                        >库存：{{ store }}</span
                    >
					<br>
                </div>
                <!--      选择规格-->
                <div
                    style="margin-top: 15px; height: 50px"
                    v-if="standards.length !== 0"
                >
                    <el-radio-group
                        v-for="(standard, index) in standards"
                        v-model="checkedStandard"
                        @change="change(standard)"
                        :key="index"
                    >
                        <el-radio-button
                            class="standard"
                            :label="standard.value"
                        ></el-radio-button>
                    </el-radio-group>
                </div>
                <!--      选择数量-->
                <div style="margin-top: 20px">
                    <el-input-number
                        v-model="count"
                        controls-position="right"
                        :min="1"
                        :max="store"
                    ></el-input-number>
                </div>
                <!--      购买按钮组-->
                <div style="margin-top: 30px">
                    <el-button
                        type="success"
                        @click="goToOrder"
                        style="font-size: 22px"
                        :disabled="isOffShelf || isSoldOutAll || (checkedStandard && store === 0)"
                    >
                        <i
                            class=""
                            style="font-size: 26px"
                        ></i
                        > 购买</el-button
                    >
                    <el-button
                        type="primary"
                        @click="addToCart"
                        style="font-size: 22px"
                        :disabled="isOffShelf || isSoldOutAll || (checkedStandard && store === 0)"
                    >
                        <i
                            class=""
                            style="font-size: 26px"
                        ></i
                        > 加入购物车</el-button
                    >
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import API from "@/utils/request";


export default {
    name: "GoodView",
    data() {
        return {
            baseApi: this.$store.state.baseApi,
            good: {},
            goodId: Number,
            price: -1,
            isDiscount: false,
            discount: "",
            standards: [],
            checkedStandard: "",
            store: 0,
            showStore: false,
            count: 1,
            totalStore: 0,
        };
    },
    methods: {
        getPriceRange(standards) {
            let arr = standards.map((item) => {
                return item.price;
            });
            //选择排序
            for (let i = 0; i < arr.length; i++) {
                // 第一次循环，假设第一个值为最小值，后面i++依此类推
                let min = i;
                for (let j = i + 1; j < arr.length; j++) {
                    // 将第一个值循环与后面的值比较，如果后面的值比第一个值小，则将索引赋值给min，直到找到最小值
                    if (arr[j] < arr[min]) {
                        min = j;
                    }
                }
                [arr[i], arr[min]] = [arr[min], arr[i]];
            }
            if (arr[0] === arr[arr.length - 1]) {
                return arr[0];
            } else {
                return arr[0] + "元 ~ " + arr[arr.length - 1];
            }
        },
        change(standard) {
            this.showStore = true;
            this.price = standard.price;
            this.store = standard.store;
        },
        goToOrder() {
            if (this.isOffShelf) {
                this.$message.error("商品已下架");
                return false;
            }
            if (this.isSoldOutAll) {
                this.$message.error("商品已售罄");
                return false;
            }
            if (this.standards.length !== 0) {
                if (this.checkedStandard === "") {
                    this.$message.warning("请选择规格");
                    return false;
                }
                if (this.store === 0) {
                    this.$message.error("该规格已售罄");
                    return false;
                }
            }
            this.$router.push({
                name: "preOrder",
                query: {
                    good: JSON.stringify(this.good),
                    realPrice: this.realPrice,
                    num: this.count,
                    standard: this.checkedStandard,
                },
            });
        },
        addToCart() {
            //未登录，拦截
            if (!localStorage.getItem("user")) {
                this.$router.push("/login");
            }
            if (this.isOffShelf) {
                this.$message.error("商品已下架");
                return false;
            }
            if (this.isSoldOutAll) {
                this.$message.error("商品已售罄");
                return false;
            }
            if (!this.checkedStandard) {
                this.$message.error("请选择规格");
                return false;
            }
            if (this.store === 0) {
                this.$message.error("该规格已售罄");
                return false;
            }
            // 从服务器获取当前用户的id，保证安全
            this.request.get("/userid").then((res) => {
                let userId = res;
                let cart = {
                    userId: userId,
                    goodId: this.goodId,
                    standard: this.checkedStandard,
                    count: this.count,
                };
                this.request.post("/api/cart", cart).then((res) => {
                    if (res.code === "200") {
                        this.$message.success("成功添加购物车");
                    }
                });
            });
        },
    },

    created() {
        //初始化商品信息
        // this.good = JSON.parse(this.$route.query.good)
        this.goodId = this.$route.params.goodId;
        this.request
            .get("/api/good/" + this.goodId)
            .then((res) => {
                if (res.code === "200") {
                    this.good = res.data;
                    let discount = this.good.discount;
                    if (discount < 1) {
                        this.isDiscount = true;
                        this.discount = discount * 10 + "折";
                    }
                } else {
                    this.$router.go(0);
                }
            })
            .catch((error) => {
                this.$message.error(error.response.data);
            });
        //从服务器获取商品规格信息
        this.request
            .get("/api/good/standard/" + this.goodId)
            .then((res) => {
                if (res.code === "200") {
                    let standards = JSON.parse(res.data);
                    this.standards = standards;
                    this.totalStore = standards.reduce((sum, item) => sum + (item.store || 0), 0);
                    //默认选择第一个标准
                    this.price = this.getPriceRange(standards);
                } else {
                    //没有规格
                    this.price = this.good.price;
                    this.store = this.good.store;
                    this.showStore = true;
                }

            })
            .catch((error) => {
                this.$message.error(error.response.data);

            });
    },
    mounted() {},
    computed: {
        isOffShelf: function () {
            return this.good && this.good.status === 0;
        },
        isSoldOutAll: function () {
            return this.totalStore === 0 && this.standards.length > 0;
        },
        //折后价，小数点后2位
        realPrice: function () {
            if (this.good.discount < 1) {
                //价格为范围，即不是数字，则返回一个范围
                if (isNaN(this.price)) {
                    let down =
                        this.price.substring(0, this.price.indexOf("元")) *
                        this.good.discount;
                    let up =
                        this.price.substring(this.price.lastIndexOf(" ")) *
                        this.good.discount;
                    return down.toFixed(2) + "元 ~ " + up.toFixed(2);
                } else {
                    return (this.price * this.good.discount).toFixed(2);
                }
            }
            return this.price;
        },
    },
};
</script>

<style scoped>
.main-box {
    width: 90%;
    max-width: 1400px;
    margin: 30px auto;
    padding: 40px;
    background-color: #ffffff;
    border-radius: 16px;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08);
    overflow: hidden;
}

.image {
    height: 100%;
    width: 350px;
}

.image-container {
    width: 480px;
    height: 480px;
    overflow: hidden;
    text-align: center;
    margin-left: 60px;
    margin-top: 20px;
    display: inline-block;
    border-radius: 12px;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
    background: #f8f9fa;
}

.image-container img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.detail-box {
    width: 480px;
    display: inline-block;
    margin-left: 60px;
    vertical-align: top;
    overflow: hidden;
}

.price-box {
    background: linear-gradient(135deg, #fff5f5 0%, #fff9f9 100%);
    border: 2px solid #ffe0e0;
    border-radius: 12px;
    font: 14px/1.8 "Microsoft Yahei", tahoma, arial;
    padding: 20px;
    margin-right: 0;
    margin-top: 25px;
}

.price-box div {
    line-height: 28px;
    margin-left: 0;
    margin-bottom: 8px;
}

.price-box div:last-child {
    margin-bottom: 0;
}

.price-box dl dt {
    float: left;
    font-size: 15px;
    line-height: 28px;
    color: #606266;
    font-weight: 500;
    min-width: 70px;
}

.price-box dl dd {
    font-size: 20px;
    line-height: 28px;
    font-weight: 600;
}

.button {
    width: 130px;
    height: 45px;
    background-color: #96e2e0;
    color: #710a0a;
}

.standard {
    height: 36px;
    margin-right: 12px;
    margin-bottom: 8px;
}

/* 响应式 */
@media (max-width: 1200px) {
    .main-box {
        width: 95%;
        padding: 30px;
    }
    
    .image-container {
        width: 400px;
        height: 400px;
        margin-left: 30px;
    }
    
    .detail-box {
        width: 400px;
        margin-left: 40px;
    }
}

@media (max-width: 1024px) {
    .image-container {
        display: block;
        width: 100%;
        max-width: 500px;
        height: auto;
        aspect-ratio: 1;
        margin: 0 auto 30px;
    }
    
    .detail-box {
        display: block;
        width: 100%;
        margin-left: 0;
    }
}

@media (max-width: 768px) {
    .main-box {
        padding: 20px;
    }
    
    .image-container {
        max-width: 100%;
    }
}
</style>
